def transform(grid):
    out = [row[:] for row in grid]
    # The colored markers on the horizontal line rise into four-cell columns.
    r = next(i for i, row in enumerate(grid) if any(v != 0 for v in row))
    for c, v in enumerate(grid[r]):
        if v not in (0, 1):
            for k in range(1, 5):
                if r-k >= 0:
                    out[r-k][c] = 1 if k < 4 else v
    return out

def transform(grid):
    out = [row[:] for row in grid]
    r = next(i for i, row in enumerate(grid) if any(v != 0 for v in row))
    for c, v in enumerate(grid[r]):
        if v not in (0, 1):
            height = 4 if v == 2 else 3
            for k in range(1, min(height, r) + 1):
                out[r-k][c] = v if k == height else 1
    return out
